"use client"

import * as React from "react"

import { type Parse, type ViewerAdapter } from "@/lib/retab"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  RetabViewerShell,
  useViewerPhase,
} from "@/components/ui/retab-viewer-shell"
import { RetabSourcePreview } from "@/components/ui/retab-source-preview"

export interface ParseViewerProps {
  parse: Parse
  /**
   * Render a single page's text. Defaults to monospace preformatted text.
   * Pass your own (e.g. a markdown renderer) to control presentation.
   */
  renderPage?: (text: string, pageIndex: number) => React.ReactNode
  /** Optional adapter; when it resolves a document URL a "Source" tab appears. */
  adapter?: ViewerAdapter
  className?: string
}

export function ParseViewer({
  parse,
  renderPage,
  adapter,
  className,
}: ParseViewerProps) {
  const pages = parse.output?.pages ?? []
  const phase = useViewerPhase({
    status: parse.status,
    error: parse.error,
    hasOutput: pages.length > 0 || Boolean(parse.output?.text),
  })

  const render = React.useCallback(
    (text: string, pageIndex: number) =>
      renderPage ? (
        renderPage(text, pageIndex)
      ) : (
        <pre className="font-mono text-xs leading-relaxed whitespace-pre-wrap">
          {text}
        </pre>
      ),
    [renderPage]
  )

  const showPerPage = pages.length > 1
  const showSource = Boolean(adapter?.getDocumentUrl && parse.file)

  return (
    <RetabViewerShell
      title={parse.file?.filename ?? "Parse"}
      status={parse.status}
      error={parse.error}
      phase={phase}
      emptyMessage="This document produced no text."
      className={className}
    >
      <Tabs defaultValue="all" className="h-full gap-0">
        <TabsList
          data-slot="parse-viewer-tabs"
          className="h-9 w-full justify-start rounded-none border-b bg-transparent px-2"
        >
          <TabsTrigger value="all">All text</TabsTrigger>
          {showPerPage
            ? pages.map((_, i) => (
                <TabsTrigger key={i} value={`page-${i}`}>
                  Page {i + 1}
                </TabsTrigger>
              ))
            : null}
          {showSource ? <TabsTrigger value="source">Source</TabsTrigger> : null}
        </TabsList>
        <TabsContent value="all" className="min-h-0 flex-1">
          <ScrollArea className="h-full">
            <div className="p-4">{render(parse.output?.text ?? "", 0)}</div>
          </ScrollArea>
        </TabsContent>
        {showPerPage
          ? pages.map((page, i) => (
              <TabsContent
                key={i}
                value={`page-${i}`}
                className="min-h-0 flex-1"
              >
                <ScrollArea className="h-full">
                  <div className="p-4">{render(page, i)}</div>
                </ScrollArea>
              </TabsContent>
            ))
          : null}
        {showSource ? (
          <TabsContent value="source" className="min-h-0 flex-1">
            <div className="h-full p-4">
              <RetabSourcePreview
                adapter={adapter}
                file={parse.file}
                className="h-full"
              />
            </div>
          </TabsContent>
        ) : null}
      </Tabs>
    </RetabViewerShell>
  )
}

export { type Parse }
